<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';
$db=cp_db(); $id=(int)($_GET['id']??0);
$st=$db->prepare("SELECT * FROM cp_print_requests WHERE id=?");$st->execute([$id]);$r=$st->fetch();
if(!$r) exit('Solicitud no encontrada.');
$st=$db->prepare("SELECT i.*,s.name size_name,m.name material_name,f.name finish_name,w.original_name,w.stored_path,w.mime_type,w.size_bytes FROM cp_print_request_items i LEFT JOIN cp_print_sizes s ON s.id=i.size_id LEFT JOIN cp_print_materials m ON m.id=i.material_id LEFT JOIN cp_print_finishes f ON f.id=i.finish_id LEFT JOIN cp_web_quote_files w ON w.id=i.file_id WHERE i.request_id=? ORDER BY i.id");$st->execute([$id]);$items=$st->fetchAll();
?>
