<body><div class="cp-wrap"><div class="cp-brand">COLIBRÍ PRINT · PRODUCCIÓN</div><div class="cp-hero"><div><h1>Solicitud #<?=$id?></h1><p><?= cp_e($r['customer_name']) ?> · <?= cp_e($r['customer_email']) ?> · <?= cp_e($r['customer_phone']) ?></p></div><a class="cp-btn cp-btn-soft" href="recepcion_impresiones.php">← Volver</a></div>
<?php if(isset($_GET['ok'])): ?><section class="cp-card" style="border-left:4px solid #18a558"><strong>✓ <?= $_GET['ok']==='completed'?'Impresión marcada como realizada.':($_GET['ok']==='archived'?'Trabajo archivado correctamente.':'Operación realizada.') ?></strong></section><?php endif; ?>
