<?php if(!in_array($r['status'],['completed','cancelled'],true) && ($r['archive_status']??'active')!=='archived'): ?><form method="post" action="print_request_action.php" style="display:inline-block;margin:0 8px 14px 0"><input type="hidden" name="csrf" value="<?=cp_e(cp_csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="complete"><button class="cp-btn cp-btn-primary" type="submit">🖨️ Marcar impresión realizada</button></form><?php endif; ?>
<?php if($r['status']==='completed' && ($r['archive_status']??'active')!=='archived'): ?><form method="post" action="print_request_action.php" style="display:inline-block;margin:0 8px 14px 0" onsubmit="return confirm('¿Conservar los archivos y el registro en el historial?')"><input type="hidden" name="csrf" value="<?=cp_e(cp_csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="archive"><button class="cp-btn cp-btn-soft" type="submit">📁 Conservar archivo + registro</button></form><form method="post" action="print_request_action.php" style="display:inline-block;margin:0 8px 14px 0" onsubmit="return confirm('Esta acción eliminará el trabajo y sus archivos. ¿Continuar?')"><input type="hidden" name="csrf" value="<?=cp_e(cp_csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="delete"><button class="cp-btn cp-btn-danger" type="submit">🗑️ Eliminar trabajo</button></form><?php endif; ?>
<table class="cp-admin-table"><tr><th>Archivo</th><th>Páginas</th><th>Configuración</th><th>Cobro</th></tr>
